-- GENERATED by `wfj generate` from data/quest/quest-0095.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("quest", {
  [95034] = { "借り", "SepulcherのLumina Windsingerと話してください。", "知っておいてほしいのだけど、道中で私たちを襲ったのは、実はGnollsではなかったの。\n\n実際に襲ってきたのは、狼のような巨大な生き物で、今では「worgen」だと知っているわ。そいつは護衛たちを片づけて私に向かってきたけど、Banonがその前に身を投げ出したの。私はなんとか呪文を放って驚かせ、追い払ったけれど、Banonはもうひどく噛まれていた。彼は自分を置いていけと言い張ったけど、私は拒んだわ。\n\n足を引きずりながらここへ戻る途中で、gnollに見つかったの。その後に起きたことは、恐ろしかった……", nil, "これで分かっただろう。gnollの刃に十数回も貫かれ、力尽きる寸前に、あいつは身を起こして私に襲いかかろうとした。その最後の瞬間、私たちは目を合わせた。あいつはまだ自分が誰なのか分かっていて、私のことも分かっているのが伝わってきた。何が起きているのか分かっていながら、自分ではどうにもできなかったんだ。それが何より辛かった。\n\nもしそんなことができるのなら、あいつを破滅させたあの獣を必ず仕留めて、二度と他の生き物にこんな恐怖を味わわせないようにしてやる。頭上の空にかけて誓う。", 0x0ff7705c, 0x84784026, 0xdc6412d7, nil, 0xb4f8e463, "...m." },
  [95036] = { "Moon-Kissedの刃", "SepulcherのTrevan Rolと話し、彼が必要とする材料を届けてください。", "Trevanによれば、worgenはSilverpine Forestの住民にとって大きな脅威だそうよ。強くてしぶといけれど殺すことはできる。でも、中に一体だけ、得体の知れない魔法のせいでどうしても死んだままでいない奴がいるの。\n\n私たちを襲ったのはそいつよ。Old Fire-Eyeと呼ばれていて、仲間の中でも一番大きくて凶暴な奴なの。あいつを仕留めるには、特別な武器が必要になるわ。\n\nTrevanと話して。そんな武器を鍛えるのに必要なものの一覧を渡してくれるはずよ。", "光があなたの刃を導いてくれると信じなさい。ですが、光にも導くに値する良い刃が必要なのです。", "必要な材料は揃ったから、あとは刃を打ってくれる鍛冶屋がいればいい。ちょうどいい鍛冶屋に心当たりがある。", 0xe7da37a4, 0x4585e62b, 0xb4f5a29b, 0x1c7078a4, 0xf4085685, "....." },
  [95041] = { "データの溜め込み屋", "Gnomeregan各地からGnomeregan Archival Dataのカードを7枚集め、IronforgeのJemma Quikswitchに届けてください。", "Gnomereganから逃げる前に、うちの一族の記録を紙に写しておいたんだ。奥義工学の場の方程式、Second Warの潜水艦の船体設計、Grandma Quikswitchのチリのレシピ……僕らの最高の業績があのファイルに詰まってる。\n\nIronforgeに着いてから、荷物に穴が開いてるのに気づいたんだ！ パンチカードが何枚かなくなってて、それがないとデータがめちゃくちゃで復元できないんだよ。\n\nカードはGnomereganの外のどこかで、雪に埋もれてるはずなんだ。探してきてくれないかな？ 望み薄なのはわかってるんだけど……", "データの回収は進んでいるか？", "このカード、少し湿ってるみたいだけど……まあ、これならなんとかなる！ ありがとう、{name}！", 0x2ec708ec, 0xdde3bae7, 0xd738032b, 0x4bbba72e, 0x87fa01c3, "....." },
  [95042] = { "Kor Gemを求めて", "AshenvaleのUlric FrostveilにKor Gemを持って行って下さい。", "Forsakenのパラディンが……このAshenvaleに？面白い。\n\nそれでKor Gemを求めているのか？驚くことでもない。Allianceのパラディンたちは、魔法の武器や道具を強化するのに時々これを使うからな。お前のような堕ちたパラディンが違うわけがあろうか？\n\n本当にその宝石の一つを望むなら、北のBlackfathom Deepsと呼ばれる遺跡へ向かわねばならない。今なおその宝石を使うnagaたちは地下にいる。一人で行くな、{class}。", "Korの宝石は大いなる悪行に使われることもある。お前の意図が清らかかどうか、私が判断することではない。私にはどうでもいいことだ。", "この宝石に染み込んだ穢れには、きっと気づくだろう。君の目的のためなら、nagaの魔女どもが宝石に注ぎ込んだ邪悪を払う魔法はごく単純なものだ。実に惜しいことだがね。こうした力からは学べることが多いのだから。\n\n宝石を探すきっかけになったクエストのことは忘れて、この宝石を私に売ってくれる気は……まあ、ないだろうね？ 私の……学術的な研究にとって貴重なものになりうるのだが。", 0x5d353131, 0x653f65b8, 0x34bb9815, 0x3e8b8507, 0x8c1b448d, "....." },
  [95065] = { "釣りの時間だ", "Shiny Baubleを$N1個とNightcrawlersを$N2個、Stormwindの港にいるGilbert Grayのところへ持って行ってください。", "なんという眺めだ……老いぼれが望める最高のものだよ。\n\n今は魚がよく食いついているんだが、餌がもう最後なんだ。まさか釣り道具の予備なんて持っていないだろうね？ いや、もちろんないよな、すまない。もう一度糸を垂らすことを考えたら嬉しくなって、どこへ行くにも道具を持ち歩く者なんてそうはいないってことに思い至らなかったよ。\n\n在庫の補充を手伝ってもらえないかな？ Catherine Lelandが、運河沿いのTrade Districtのすぐ西でいろいろな釣り道具を扱っている。老いぼれのGrayの使いだと言ってくれ。", "釣り道具は手に入れたか？", "いいところに来たな！ 最後の餌で大物を釣り上げたところだ。今日はここまで上々だよ。ここはよく食いつくんだ！\n\nそうだ、このじいさんの商売を助けてくれたお礼に、道中用に魚を何匹か持っていかないか？", 0x50ff1618, 0x1ca3ae56, 0x4f6c7d2d, 0x630eca56, 0x7cc547b8, "....." },
  [95111] = { "過小評価された才能", "Ottと話し、あなたの剣を鍛えてくれるよう頼む。", "Tarren MillにはOttという武器鍛冶がいる。誰に聞いても、旅人に簡素な剣を売るだけの平凡な鍛冶屋だそうだ。私も彼から剣を一振り買ったのだが、しばらくして手入れのためにUndercityへ持っていくと、そこの鍛冶屋たちがその出来に驚いていた。名の知れた名工の作だと思い込んでいたが、違う、それはただのOttだったのだ。\n\nこのオークに、本当に特別な仕事をする機会を与えたい。材料をTarren MillのOttに届けて、依頼を申し出てくれ。", "剣が入り用か、{class}？", "面白い。実際に特注の仕事を頼まれたことなんて、たぶん一度もないな。たいていは自分のやり方で、質素で実用的な武器を作っているだけだ。大したものじゃないが、まっとうな仕事だし、称賛や栄光を求めてもいない。\n\n喜んでやってみるが、なぜ俺のところに？ Undercityには、こういう特注の仕事を引き受ける鍛冶屋がいくらでもいるぞ。", 0x2c5a8af0, 0x57d2ed34, 0x9137acf7, 0x45d644e4, 0xc6b81f00, "....." },
  [95125] = { "Ott's Masterwork", "Ottがあなたの剣を鍛えるのを見届ける。", "これは実に見事な素材だな、{class}。この剣を鍛えさせてくれるとは光栄だ。期待に応えられるといいんだが。\n\nさあ、少し下がっていてくれ。鍛造を始めるからな。", nil, "この刃は俺の最高傑作だ。旅の役に立ってくれることを願っている。この機会を与えてくれて、改めて礼を言う。\n\nAka'Magosh、友よ。", 0x2af2ae36, 0xa5330aaf, 0xa0a0368f, nil, 0xee452c14, "...m." },
  [95126] = { "Moonsilver Blade", "Ott's MasterworkをSilverpine ForestのTrevan Rolに届ける。", "これが剣だ。Trevanという名のパラディンに言われて来たと言ったな? 今度会ったら、この機会をくれた礼を伝えてくれ。誇りを持って行け、友よ。", "Ottは依頼を果たせたか？", "<Trevanは刃を受け取り、注意深く調べる。>\n\nこれなら申し分ない、{name}。Ottには本当に素晴らしいものを作る力があると分かっていたよ。\n\n残るはあの獣を仕留めることだけだ。準備ができたらLuminaと話してくれ。", 0x774c6075, 0xb9d5e27a, 0xac0b5a01, 0xaf39b5e9, 0x469d97a1, "....." },
  [95140] = { "Old Fire-Eye", "Moonsilver Bladeを使って、Silverpine ForestのOld Fire-Eyeを倒して下さい。", "武器を手に入れたようだな、{class}。それがお前を裏切らぬよう祈っている。\n\n地元の者の話では、Old Fire-Eyeはここから南の広い範囲で狩りをしていて、たいていはGilneasの門の近くで見つかるそうだ。奴を見つけ、新しい剣で仕留めてくれ。それが済んだら戻ってこい。Windshaperたちの感謝を受けるだろう。", "済んだか？獣は倒されたか？", "ありがとう、{name}。これでBanonも安らかに眠れるでしょう。\n\nもし許してもらえるなら、血を浴びたばかりのあなたの刃に魔法を授け、私たちの民の魔法をほんの少し宿らせることができると思います。\n\n<Lumina Windsingerの目が鮮やかな青に輝き始め、彼女はあなたの手にある血に染まった刃に触れる。>\n\n終わりました。ささやかなものです。これほど見事な刃を私が良くすることなど、ほとんどできませんから。それでも、この刃があなたの役に立つよう風に祈ります、{class}。", 0x1db24010, 0xee598827, 0x2f1bb8e0, 0x95a43f2e, 0xb76eccca, "....." },
  [95161] = { "愛していると忘れないで", "Blood-Stained LetterをDuskwoodのAvette Fellwoodに届けてください。", "Jeremy Heartweaverを探しているなら、一番いいのは、Duskwoodにいる彼の新しい養母、Avette Fellwoodに話を聞くことだね。優しい人だよ。仕事の人手がもう一人ほしいんだろうけど、孤児院にいるよりはましだろう。\n\nもし小さなJeremyに会ったら、みんなあの子のことを思っているって、ちゃんと伝えてくれるかい？", "何だ？何が要る？", "ああ、そんな……\n\n持ってきてくれたのはありがたいけれど、Jeremyにはまだ見せられないと思うわ。Matron Nightingaleの話では、うちのJeremyはLordaeronが襲われてから一言も話していないそうなの。今、無理をさせるつもりはないわ。これを見せたら、あの子をもっと苦しめるだけよ。\n\nそんな目で見ないで。あの子の過去を隠すつもりはないけれど、癒えるには時間が必要なの。大きくなったら渡すわ。来てくれてありがとう。でも、もう帰ったほうがいいと思うわ。", 0x920a601f, 0xa5aac85c, 0xab5e3e2b, 0x664e4a5c, 0xbb9d2166, "....." },
  [95189] = { "Crest of Lordaeron", "Crest of LordaeronをStormwind CityのLady Dena Kennedyに返してください。", "<Lordaeronの紋章が描かれた、風雨にさらされた紋章だ。王国の滅亡後に残った遺物はごくわずかなので、Stormwindの誰かがぜひとも手に入れたがるだろう。>", nil, nil, 0x98ec1516, 0xea3f7a39, 0x6f2a4873, nil, nil, "...mm" },
  [95195] = { "Bloodied Insignia", "Bloodied Insigniaを$N1個集め、Stormwind CityにいるGeneral Marcus Jonathanのところへ持って行ってください。", "<この古いAllianceの記章は、Lordaeronの兵士のものだったようだ。この遺跡には、きっと同じような勲章がたくさん眠っていて、生きている身内は返してもらえればありがたく思うだろう。>", "重い荷を背負っているように見えるな、{name}。どうしたのだ？", "これを私のもとへ持ってきたあなたの直感は正しかった。LordaeronがScourgeの手に落ちたとき、多くの人々がここStormwindへ逃れてきた。自らこの記章を受け取りに来られる者は、もうほとんど残っていないだろう。\n\nStormwindへの務め、見事だ、{name}。すぐにこの記章を近親者たちに配り始めよう。", 0xfb70dfc5, 0xf9dfef5a, 0x2c958367, 0x3d6daf5e, 0x351f4fdf, "....." },
  [95204] = { "Crest of Lordaeron", "Crest of LordaeronをUndercityのOran Snakewritheに届けてください。", "<Lordaeronの紋章が描かれた、風雨にさらされた紋章だ。王国の滅亡後に残った遺物はごくわずかなので、Undercityの誰かがぜひとも手に入れたがるだろう。>", "そこに何を持っているんだ、{class}？うまそうな一口か？", "<Oranは本物かどうか確かめるために紋章をかじる。>\n\nこいつは驚いた。故郷の本物の遺物だ。ほとんど傷もない。こいつは特に慎重に扱わないとな。\n\n我々の歴史を取り戻す手助けをしてくれてありがとう、{class}。こいつは責任を持って大切に保管するよ。", 0x98ec1516, 0x937c7b4b, 0x992e7722, 0x059931e7, 0xc46da411, "....." },
  [95212] = { "鞍に妥協なし", "Pristine Leopard Peltsを6枚集め、Amberstill Ranchに届けてください。", "Alterac遠征隊の増援に雄羊の隊を送る準備をしているんだが、鞍を作る材料が切れてしまったんだ。\n\n東にいる一番大きくて獰猛な豹の毛皮を集めて持ってきてくれ。あそこは身を切るような寒さだ。我らの部隊には、暖を取るための最高の毛皮こそふさわしい！", "寒そうだな、{class}。狩りの調子はどうだ？", "この毛皮なら上等な鞍ができる。Allianceの誇りだぞ、{class}！", 0x07df31f7, 0x270babaf, 0xb5c3ab85, 0x545929d0, 0xcdcfccf7, "....." },
  [95213] = { "Stolen Blasting Powder", "Empty Powder KegをGol'Bolar QuarryのQuarrymaster Thestenに届けてください。", "樽には刻印がある。\n\n発破用火薬 - 危険 - 取扱禁止 - 危険 - 採石場長の許可者のみ - 危険\n\ntroggがこれを持っているべきではないという嫌な予感がする。できるだけ早く採石場に報告した方がいいだろう。", "何を持っているんだ？", "<空の樽を見て、ドワーフの顔が青ざめる。>\n\n……これをどこで見つけた？", 0x8848eca5, 0xd56ef55e, 0xf1f411df, 0xac2369a3, 0x28899f23, "....." },
  [95214] = { "Stolen Blasting Powder", "Gol'Bolar Quarryの東にいるtroggからStolen Blasting Powderを$N1個取り戻し、Quarrymaster Thestenのところへ戻ってください。", "この樽には、King Magniの玉座の間を吹きさらしの中庭に変えてしまえるほどの火薬が入っていた。troggどもが火のつけ方に気づく前に、取り返さなきゃならん。", "良い知らせを持ってきてくれたんだろうな？", nil, 0x8848eca5, 0x4fe59366, 0xcc857a5c, 0xb50481e8, nil, "....m" },
  [95216] = { "新たな疫病", "UndercityのTheodore Griffsのために、Ruins of LordaeronのWitherfangからHighly Toxic Strainを手に入れてください。", "Undercityで最も重要な臓器、The Apothecariumへようこそ！ ここではAzerothの珍しい標本の中でも最も毒性の強いものを使って実験しているのです。\n\n今は機嫌がいいので、私の最新の研究について教えてあげましょう。どうやら、我らが麗しき街の上の廃墟に、特に毒の強い節足動物がうろついているらしいのです。その毒はアンデッドの肉さえも溶かすと言われています。なんと胸躍ることでしょう！\n\nこの話を確かめたいのです。もしその咬み傷で体が朽ちていくようなことがあれば、ぜひ見本をいただきたいですね。", "最も強力な感染経路は常に血液だ、そんなことは愚か者でも分かる。\n\nこの菌株を自分の目で確かめねばならん！", "殺しただと？？\n\nふん。運のいい奴め、これだけの体液があれば、その性質を逆解析できるはずだ。Royal Apothecary Societyを敵に回したくはないだろう。\n\n私の前から消え失せろ！", 0xbf7a7e24, 0xec263960, 0x9214d563, 0x5c8c63f0, 0x8f9e0d7b, "....." },
  [95217] = { "採石場の鍛冶屋", "Copper Barsを12本とToughened Boar Hidesを4枚集め、Frast Doknerに届けてください。", "鍛冶屋の仕事を学びたいってのか？ だったら、お互い助け合えるかもしれないな。\n\n補給品の輸送が遅れていて、野営地のあちこちを修理する材料が要るんだ。必要なものを持ってきてくれたら、俺の技をいくつか教えてやろう。悪くない話だろ？", "怠けるなよ、{name}。鍛冶は怠け者には務まらんぞ！", "なかなか機転が利くな、{name}。\n\nさあ、よく聞け。二度は言わないぞ！", 0xcf9ba453, 0x56fdeb4f, 0xd3803ca1, 0x8461c8b8, 0x9e396b99, "....." },
  [95250] = { "忌まわしき怪物", "Ruins of LordaeronでHead of the Baronを手に入れ、Captain Trumanのもとへ持ち帰ってください。", "何の用だ、{race}？ 勝たねばならん戦があるのが見えんのか？\n\n主人はすでに戦いのただ中へ突撃していき、私には持ち場を守るよう命じられた。だが、もうかなりの時間が経っている。\n\nお前が戦場で10分も生き延びられるとは思えんが、その単純な頭の暇つぶしになるなら、Grand Marshalを探してみたらどうだ。お前がこれまで目にした中で最も背が高く、最も堂々とした英雄だ。見ればすぐにわかるだろう。", nil, nil, 0x83266151, 0xb8e0ac06, 0x0f67af09, nil, nil, "...mm" },
  [95314] = { "あのShadowvaleの緑の霊薬", "ShadowvaleでBottles of Whispering Elixirを$N1本集め、BrillにいるCarolai Aniseのところへ戻ってください。", "Scourgeの侵攻以前、人里離れたShadowvaleの村はWhispering Elixirで知られていた。Tyr's Fallにしか生えない薬草から蒸留されたその霊薬は、街で禁じられた後でさえ、薬師や神秘家、毒使いにまで求められていたんだ。\n\n何人もの買い手から、その霊薬が欲しいと頼まれている。西のWhispering Forestの奥深くにあるShadowvaleの廃墟へ行ってくれ。何本か取り戻してくれたら、たっぷり報酬を出す用意がある。", "道に迷わなかっただろうな？", "Shadowvaleに邪悪なものがいるだと？ 正直、驚きはしない。森の民は風変わりな連中で、よそ者を好まなかった。Whispering Forestそのものが呪われていると信じる者もいるし、その根から蒸留した霊薬にも同じ呪いがかかっているという……\n\n……だが迷信や噂の話はもう十分だ、{name}。霊薬をありがとう。ほら、代金としてこれを受け取ってくれ。", 0x62c6b7bf, 0xff6777a1, 0x5740e013, 0x46ba8900, 0x23664c51, "....." },
  [95328] = { "Whispering Horror Residue", "Whispering Horror ResidueをUndercityのWar QuarterにいるFather Lankesterに届けてください。", "気は進まないものの、あなたは獣のうごめく残骸をこそげ取って集める。Undercityの誰かなら使い道があるかもしれない。", "何か私に渡すものがあるのか、{class}？", nil, 0xb283ff1d, 0xa13a9b4c, 0x1336682a, 0xcbd58f92, nil, "....m" },
  [95349] = { "Earthen Ring", "Zephras IsleからMulgore行きのスカイカッター船に乗り、到着したらAlaana Stormwalkerと話して下さい。", "カルトをめぐる最近の出来事でAzerothへ渡る予定が遅れ、しばらくはここValanaarに残らねばならない。代わりに、君と数人のWindshaperたちが我々の先遣隊となる。MulgoreではAlaana StormwalkerがWindshaperの到着を待っている。我々がここの用事を片付ける間、Azerothを探索してほしい。我々もすぐに合流する。\n\n準備ができたら、このロッジのすぐ外の桟橋へ行き、そこのskycutter船に乗ってくれ。\n\nBanu-Alah、{name}。", nil, "またZephrasから冒険者が来たか。何よりだ。風は間違いなく我々に味方している！ ここで落ち着くまでにはしばらく時間がかかるから、その間にこの新しい土地を見て回るといい。\n\nAzerothは胸躍る新世界だが、危険な世界でもある。この新たな冒険に備えて、近くの土地をよく知っておくといいだろう。", 0x28da0b16, 0x74e6dafa, 0x76858aa9, nil, 0xde8ad8f1, "...m." },
  [95350] = { "Azerothへようこそ", "Orgrimmarへ行き、Valley of WisdomにいるThrallと話してください。", "この下の世界は広い。そして我々の新しい盟友こそが、我々が生き残るための鍵だ。\n\nEarthen Ringは、志を同じくする民の誇り高き集まりである「Horde」の一員だ。近くのThunder Bluffの街もHordeの一部で、さらに東には首都Orgrimmarがある。\n\nThunder Bluffの中心にいるフライトマスターを訪ねるといい。Orgrimmarまで乗せていってくれる。そこでWindshapersの代表として、Hordeの大族長、Thrallと接触するのだ。風がお前を導かんことを、{name}。", nil, "Lok-tar、{class}。私はThrall、Hordeの大族長だ。\n\nEarthen Ringの使者から、Windshapersの者たちを迎えることになると聞いていたが、こうしてお前がいる。ここOrgrimmarでハイエルフが目の前に立つとは思いもしなかったが、それでもHordeはお前を客人として歓迎する。\n\nHordeの領地を旅することを認めよう。名誉と共に行け、Windshaper。", 0x2f003d6f, 0x53ee86b6, 0x7024f167, nil, 0x328b0c81, "...m." },
  [95494] = { "傷ついた誇りとライオンの皮", "BarrensのSavannah MatriarchsとSavannah Patriarchsから、Savannah Lion Hidesを6枚集めてください。", "剣の腕が立って、時間に余裕のある者に、ライオンの皮集めを手伝ってほしい。見知らぬ者にこんな助けを頼むのは誇りが傷つくが、最近脚を怪我してしまってな。治るまでは自分で狩りに出られる状態じゃないが、果たさねばならん約束がある。\n\nこのあたりでは、大きな奴ほどたいてい皮が上等だ。まずはそいつらから始めてくれ。", "狩りの調子はどうだ？", nil, 0x5b2ff02d, 0xce49bfcd, 0x5cce729a, 0xe02b27bb, nil, "....m" },
  [95495] = { "隠者の皮なめし職人", "Bundle of Hidesを、BarrensのDry Hillsを見下ろす尾根にいる隠者に届けてください。", "この皮は、よく取引している皮なめし職人に届けるものだ。そいつはちょっとした世捨て人で、俺の後ろの尾根の頂上にひとりで住んでいる。今の俺には急な斜面を登るのは楽じゃないから、代わりに届けてくれたら恩に着る。\n\nああ、それと、その皮なめし職人の……見た目のことだが。驚かなくていい。見た目はああだが、危険はない。これは本当だと誓う。", "ようこそ、{class}。今日は何の用で私の土地まで来たのかね？", nil, 0xc91f6041, 0x2e6fcebc, 0xf3a9275e, 0xbe27a510, nil, "....m" },
  [95507] = { "Vrangの獲物", "BarrensのSprung Trapsにある罠から、Trapped Gameを8つ集めてください。", "外に出ているついでに、俺の罠を見てきてくれるとすごく助かる。谷じゅうにばらまいてあるんだ。\n\nかかっている小さな獲物を持ってきてくれ。ただ、他の野生の動物には気をつけろよ。このあたりは、気を抜いていると危ないからな。", nil, nil, 0x56a6a9a8, 0xc7e5f7a1, 0xd203b57b, nil, nil, "...mm" },
  [95508] = { "招かれざる客", "Terry LongdrinkとKul Tirasの海兵隊との遭遇を、Waltonが生き延びられるよう手助けしてください。", "ああ、かつてはKul Tirasの海軍にいた。Lord AdmiralがTheramoreを奪ってDurotarでの作戦を始めた後、俺はそのやり方に……「異議」があってな。特に、民間人を処刑するやり方にだ。\n\n話にはまだ続きがあるんだが……待て……あれは何だ？\n\n男たちの一団が尾根を登ってくるぞ！", nil, "さて、どうやら皆生きているようだな。私は……いつかあれに追いつかれると分かっていた。今日ここで助けてもらった恩は忘れない。\n\nどうか、これを受け取ってくれ。大したものではないが、せめてもの礼だ。\n\n道中気をつけて、{class}。", 0xaedbb4a0, 0xfb874c5b, 0x5b6957f0, nil, 0xd4531345, "...m." },
  [95534] = { "Strahnbradの謎", "Strahnbradの謎を解き、Hillsbradの町で調べた結果を報告する。", "<メモはところどころ焦げているが、まだ読める。>\n\n噂では、あの古いふいごは意志を持っていて、誰も見ていないときに勝手に動き出すらしい。怪談だろうが知ったことではない。私が戻る前に真相を突き止めておけ。\n\nStrahnbradには大きな力がある。私には分かる。\n\n< メモの残りは、炎の魔法で焼かれたかのように焦げて破れている。 >", nil, nil, 0x84d1d4cf, 0xe5975afe, 0x53e7de0b, nil, nil, "...mm" },
  [95621] = { "谷の異変", "壊されたキャラバンへ行き、Kul Tiransがなぜここにいるのかを探ってください。", "今朝、下の谷で何かを探している人間の一団を見つけた。ライフルのスコープでよく見てみたら、Kul Tirasの紋章をつけた兵士なのは明らかだった。\n\n俺からの仕事を引き受けてくれるなら、南の壊れた隊商のそばにある、そいつらの野営地へ行ってくれ。見つけた奴は殺して、なぜここにいるのか探ってくれ。", "いまだにDaelin Proudmooreの旗を掲げる艦隊の残党どもは、死ぬ前の提督本人と同じく腐りきった野蛮な連中だ。\n\nなぜTiragardeからこれほど離れた場所にいるのかは分からんが、良いことのはずがない。", nil, 0x389c29a3, 0xef54682f, 0xcaabc078, 0xdcde325c, nil, "....m" },
  [95646] = { "Highlandの恐怖", "Excavation Sitesの中でHighland Horrorを倒し、その根の核をWetlandsのRethiel the Greenwardenのところへ持って行って下さい。", "この汽水の湿地には、南からの塩気のない水がより多く湛えられている。心が痛むが、我が根の内に、あの山の峡谷を伝って染み出す穢れを感じるのだ。\n\nこの地の生き物たちは、我らの低地の者たちと同じく、穢れにより激しく反応する。生命の夜明けより海の硬き塩を知らぬゆえ、かような邪悪に抗う力がほとんどないのだ。\n\nあの高地へ行き、Highland Horrorの根の核を我が元へ持ってくるのだ。", nil, nil, 0x79650957, 0x81ee8465, 0xbce12a7e, nil, nil, "...mm" },
  [95647] = { "茂みに消えたもの", "Excavation SitesでArdin Grassmanを見つけて下さい。", "夫のArdinには、自然を感じ取る稀な才能があるの。私の錬金術に必要な薬草や花を摘むためなら、どんな峰にも登って、うちの棚と食料庫をいっぱいにしてくれるわ。\n\nでも、何か厄介事に巻き込まれたんじゃないかと心配なの。発掘隊が物資を求めてここを通ったのよ。彼らはいろいろな話の中で、見たこともないほど高くそびえる草のことを話していたわ。夫は、それを自分の目で確かめに行かなくちゃって言っていたの。もう帰りが遅すぎるわ！\n\n彼について何か分かったら、ありがたいわ。", nil, nil, 0xc3371e69, 0x4d0fc432, 0x6d7c1497, nil, nil, "...mm" },
  [95663] = { "Dragonmawの噂", "Wetlandsへ行き、Dragonmawの野営地の上にある丘でDeathstalker Agentに会って下さい。", "Dragonmawは手強い氏族だ。\n\n奴らはドラゴンをも従わせるほど強力な束縛の魔法で知られており、Wetlandsでその力を見せつける準備をしているという噂だ。真実か虚勢かはともかく、Deathstalkersは中途半端な囁きでは動けない。大いなる風が私に運んできたのは、それだけだ。\n\nDragonmawの野営地の上の丘で、deathstalkerの諜報員が手を必要としている。そこで彼女と会え。次の手順を教えてくれるだろう。", nil, nil, 0xecfb9de3, 0x607aac05, 0xdb2a81bc, nil, nil, "...mm" },
  [95664] = { "長老の知識", "Titan RelicをThunder BluffのElder Riseへ持って行き、それについて詳しく教えてくれる人を探して下さい。", "この珍しい複合物の欠片は、生きたプリズムのように光を散らす。その性質は定かではないが、その力は古のものに感じられる。この過ぎ去った時代の遺物に最も詳しい者たちは、Thunder BluffのElder riseにいるに違いない。", nil, nil, 0x1d764e46, 0x4a860375, 0xd36a8f92, nil, nil, "...mm" },
  [95682] = { "大口を開く", "Excavation Site内のDragonmawの軍勢を倒し、回収した物を持って外にいるDeathstalker Agentのところへ戻って下さい。", "Dragonmawね。<彼女は乾いた、面白がるような嘲笑を漏らす。>\n\nあのドラゴン使いの氏族の残党は、かつての力を取り戻すきっかけになるものを見つけたと思い込んでいる。誰の目から見ての話かしら……あの偽りの大族長？\n\nExcavation Sitesにいるあの寄せ集めの氏族を一掃して、我々のDeathstalkersが気づかれずに入り込めるようにしなさい。\n\nDragonmawが何か目ぼしいものを身につけていたら、私のところへ持ち帰りなさい。この情報は、我々と王家の司令部の間だけに留めておかねばならないの。", nil, nil, 0x01716485, 0x9fb46d83, 0x5cd87c72, nil, nil, "...mm" },
  [95697] = { "変わる好み", "WetlandsのExcavation Sitesに入り、Thicket Raptor Meatを持ち帰って下さい。", "Zamjaが言うには、家庭料理がもっと必要らしい。\nraptorを売り始めれば、普段Borstan's Firepitに来ない客も呼び込めると考えているんだ。\n\n彼女の考えも悪くない。だが俺は、俺たちの生まれた村の匂いを超えるものが欲しい。ここはOrgrimmarだぞ！ Borstanは、皆が慣れ親しんだ好物を壮大に仕立てたものを出すべきだ。\n\n最近、あるハンターがWetlandsから戻ってきた。Excavation Sitesのthicket raptorsの巨大な鉤爪を持ってな。\n\n仕事を引き受けるか？", nil, nil, 0xefd7f8a7, 0x406ca9c2, 0xc77dbee9, nil, nil, "...mm" },
  [95737] = { "Caitlinを探して", "Menethil HarborのCaitlin Grassmanと話して下さい。", "時々、私は同業の者たち、つまり珍しい植物や土地の奇妙なものを研究する薬草学者や変わり者たちと手紙をやり取りしています。発見を交換し合い、ときにはこの先に待つものについての警告も交わすのです。\n\nWetlandsのある錬金術師が、夫の加わっている発掘隊のことを書いてきました。長く失われていた原初の草の痕跡を見つけたというのです……でも、それがどれほどあって、どれほど手に入れやすいのかは、知らせてきませんでした。\n\nもしできるなら、Menethil HarborのCaitlin Grassmanの様子を見てきてください。", nil, nil, 0xf6e09b80, 0x29283070, 0xb0744041, nil, nil, "...mm" },
  [95748] = { "Gurubashiの古き伝説", "皮と木炭を使って、Third Troll Legendの石板の拓本を取る。", "これは妙だ。あなたが持ってきてくれた石板のこの部分は、失われた都市I'lalaiを、まるで広大に広がる巨大な文明であるかのように語っている。だが、岩礁の沖にある遺跡は、それほどの規模のものにしては小さすぎる。\n\n{name}、Vile Reefの北の海岸沿いの丘に、古いトロールの遺跡がある。その中に、失われたトロールの都市の伝説が刻まれた石板があるのだ。この伝説をさらに調べたい。\n\nこの皮と木炭を持っていって、その石板の拓本を取り、私のところへ戻ってきてくれ。", nil, nil, 0x1163f14b, 0x8eb3fa59, 0x85f90475, nil, nil, "...mm" },
  [95770] = { "失われた都市を探して", "Vile Reefを探索し、洞窟の入口を見つける。", "伝説を読み返したところ、失われた都市の場所を間違えているわけではなさそうだ。だが、まだ見落とされている細部があるのかもしれない。\n\n若い頃、私はVile Reefの遺跡によく潜っていたものだが、それはmurlocがそこに住み着く前のことだ。記憶が確かなら、そこには洞窟があった。\n\n今その辺りにnagaが集まっていると聞いた。珍しいことだ。何が奴らをそこへおびき寄せたのか知りたい。\n\nVile Reefのすぐ西を探索して、何か分かったら私のところへ戻ってきてくれ。", nil, nil, 0xbfc53c6c, 0x5befc8cb, 0xba46d29c, nil, nil, "...mm" },
  [95771] = { "闇の味", nil, nil, nil, nil, 0x8583a882, nil, nil, nil, nil, ".mmmm" },
  [95772] = { "Songbladeの捜索", "Whelgar's Excavation Siteで、Dorin Songbladeの兄弟Daewynを探して下さい。", "兄貴の奴、Loch Modanから来た発掘屋の連中と一緒に、俺をWetlandsへ引っ張っていこうとしたんだ。ドワーフが一人も足を踏み入れたことのない丘へ、何かの発掘に向かうって言ってたな。\n\nああ、行ってたさ。この山ほどのベルトの直しが遅れてなきゃな。\n\nだがDaewynは普段、出発した後に手紙をよこすんだ。今回は何の音沙汰もねえ。妙な胸騒ぎがするんだよ。\n\nそっちへ行くなら、兄貴の様子を見てきてくれねえか？", nil, nil, 0x4225ee40, 0x72145fde, 0x91fbce45, nil, nil, "...mm" },
  [95773] = { "水中の敵", "Brinescale SkirmishersからBrinescale Tridentsを$N1本集める。", "{class}、ちょうどいいところに来たな。我々の海岸のすぐ沖でnagaが活動しているという新しい報告を受けたばかりだ。奴らは海底近くの古いトロールの遺跡の周りに群がっているらしい。\n\n我々は地元のBloodscalpや、隊商を荒らすogreからの防衛ですでに手一杯だ。海からの奇襲を受ける余裕はない。\n\n行って、できるだけ多く倒し、成果の証として奴らの三叉槍を持ってきてくれ。", nil, nil, 0xf6a51353, 0x23c1e22b, 0xbd430784, nil, nil, "...mm" },
  [95774] = { "彼女の名はOlgra", "quilboarを倒し、Mankrikの弔いのためにOlgra's Adornmentsを$N1個集めてください。", "私を救ってくれた治療師も、彼女を救うことはできなかった。彼女は戦いの中で死んだのだ。名はOlgra。私は決して彼女を忘れない。\n\n彼女の遺体に飾りはなかったのか？ 磨いた骨の宝飾をたくさん身につけていたのだが。\n\n彼女が倒れたあたりにいるRazormane Raidersを倒し、彼女の大切な作品を見つけてきてくれ！\n\n彼女を偲んで私が建てる記念碑に、それを添えるつもりだ。", "今の私には思い出しかない。だが、それが色あせることのないよう、Olgraをたたえる記念碑を建てるつもりだ。", "この装飾品は妻の慰霊碑に供えよう。彼女を決して忘れないように。我が血は永遠に復讐に燃え続ける！\n\nお前は私に……いや、我々に……大きな恩を施してくれた、{name}。", 0xe0733c23, 0x64b2ed87, 0x1085cf6b, 0xcb32b1fe, 0x22fd675b, "....." },
  [95775] = { "Drowned City", "皮と木炭を使って、Drowned Cityで見つかる石板の拓本を取る。", "これから頼むことは決して容易なことではないぞ、{class}。成し遂げるには、おそらく強い仲間が必要だろう。\n\nnagaが守っている洞窟の向こう側にある遺跡について、もっと知りたい。私の推測が正しければ、それはまさしく失われた都市I'lalaiかもしれない。手に入る失われた歴史の知識の量は比類ないものになるだろうが、私は年を取りすぎて自分では行けない。\n\n遺跡に入り、そこで見つけた石板の拓本を取って、私のところへ戻ってきてくれ。", nil, nil, 0x7b66254a, 0xda9d19e9, 0xf184a1b6, nil, nil, "...mm" },
  [95776] = { "良いBrinescaleとは……", "Drowned CityでVar'Takaを倒す。", "我々の海岸のすぐ沖でnagaを倒してくれたのは見事だった。だが、奴らがこれほどの数で我々の海域にいるということは、さらに大きな脅威があるということだ。\n\nKin'weelayと話したところ、彼はこのBrinescaleのnagaがDrowned Cityの遺跡に入り込んでいると考えている。nagaがそこにいるなら、何か良からぬことを企んでいて、おそらく何かを探しているのだろう。\n\nここの我々を危うくするようなものを奴らの手に渡すわけにはいかない。これに終止符を打つ時だ。奴らの指導者を倒し、私のところへ戻ってきてくれ。", nil, nil, 0x6893b9a2, 0x0ab0d353, 0xee8da360, nil, nil, "...mm" },
  [95795] = { "沼地に倒れた者", "Dorin Songbladeのところへ戻って下さい。", "<あなたはドワーフの亡骸を、彼のマントで覆った。>\n\nLakeshireへ向かい、Dorin Songbladeに、彼の兄弟がExcavation Sitesでどうなったのかを自ら伝えよう。", nil, nil, 0xbfc85885, 0x2739cdb1, 0x9e5ae38b, nil, nil, "...mm" },
  [95803] = { "誠意の証", "Rudolph Gelhardtの首をUndercityのSylvanas Windrunnerに届けてください。", "汚れた司令官の首を取った今、それをUndercityへ届けてもらいたい。Sylvanas Windrunnerは我々をひどく疑っていて、ほとんどあからさまに見下している。\n\nRudolph Gelhardtの首をDark Ladyに届けろ。我々が自分たちの家の始末は自分でつけ、Forsakenの繁栄に身を捧げていることを示すのだ。", "なぜ私に話しかける、{class}？", "お前たちの種族のためにForsakenの中に居場所を勝ち取りたいというDanithaの誠意と願いは疑っていない。だが、お前の兄弟姉妹の誰かが狂い、光を自らの同胞に向けるのを目にするのは、これが最後ではないだろう。\n\nお前たちの忌まわしい教団を容認することが、もはやForsakenの利益にならないと判断する時が来るかもしれない。せいぜい民に忠実に仕え続けることだ。\n\n我々は見ているぞ。", 0x8a963535, 0x09f1d511, 0x27427458, 0x2d8b7e5f, 0x2b29670e, "....." },
  [95805] = { "An'sheとMu'shaの恩寵", "香が10分で燃え尽きる前に、Smoldering Incenseを南東の丘にあるAn'sheとMu'shaの祠へ運んでください！", "太陽と月、An'sheとMu'shaは、精霊のようにこの世界の一部ではありません。けれどもその光は、私たちに命と導きと希望を与えてくれます。\n\n私たちは世界の精霊に敬意を払います。ですから、双子にも敬意を払うのです。\n\nあなたも敬意を示したいのなら、このくすぶるお香を持って、南東の丘にある祠へ届けてください。台地を見下ろす、quilboarの南にある祠です。お香が燃え尽きる前に祠にたどり着けるよう、急いでください。\n\n濡らしてはいけませんよ！", "<香の煙が空へと立ち昇っている。>", "<香を火の中に空けると、その香りがあたりに漂い、あなたの手には空になった袋と、かすかな達成感だけが残った。>", 0x1483f5df, 0x82228fe2, 0x52a83811, 0xd4bc4ea6, 0xd28f1b93, "....." },
  [95809] = { "Heartwoven", "Menethil HarborのCaitlin Grassmanのところへ戻って下さい。", "自分で道を見つけて出ていく前に、少し休ませてくれ。\n\n<彼は荷物から葦を何本か取り出し、手早く編んで曲げ、ハートの形にする。>\n\nこれを持って、Caitlinに届けてくれ。もうすぐ帰ると伝えてほしい！ 君のおかげで道が開けたから、俺は自分の束をまとめて君の後を追うよ。\n\nありがとう。", nil, nil, 0x7c49eff3, 0xb6ab7769, 0x84c0de8c, nil, nil, "...mm" },
  [95810] = { "失われた遺物の運搬", "Titan RelicをWetlandsの発掘現場にいるProspector Whelgarのところへ持って行って下さい。", "あなたは岩の機械仕掛けの自動人形の、砕けた破片を拾い上げる。これまで触れたどんなものとも違う手触りで、正体不明の複合素材でできている。これは間違いなく「残骸」というより「装置」だろう。\n\nProspector Whelgarなら、自分の発掘現場でこの遺物について役に立つ話をしてくれるかもしれない。", nil, nil, 0x66a19050, 0x25ed1b64, 0x09d52652, nil, nil, "...mm" },
  [95816] = { "参加させてくれ！", "記入済みの書類をRedridge MountainsのElaine Comptonに届けてください。", "熟練の職人の皆さま、ごきげんよう！\n\nこの用紙にご記入いただくと、Azeroth全土であなたの生産スキルの広告看板を掲げる、非独占的・取消可能・法的に限定された許可が得られます！\n\nご記入後は、手続き開始のため、お近くのAzeroth Commerce Authority支部のContract Coordinatorまでお持ちください。\n\n楽しい物作りを！", nil, nil, 0xe71188a6, 0xaef04737, 0x5eb40123, nil, nil, "...mm" },
  [95819] = { "参加させてくれ！", "記入済みの書類をThe BarrensのJornahに届けてください。", "熟練の職人の皆さま、ごきげんよう！\n\nこの用紙にご記入いただくと、Azeroth全土であなたの生産スキルの広告看板を掲げる、非独占的・取消可能・法的に限定された許可が得られます！\n\nご記入後は、手続き開始のため、お近くのDurotar Supply & LogisticsのContract Coordinatorまでお持ちください。\n\n楽しい物作りを！", nil, nil, 0xe71188a6, 0x73fcb0bd, 0xb6355654, nil, nil, "...mm" },
  [95883] = { "Tortured Soul", "Silverpine ForestのBeren's Perilにいる近くのアンデッドから、Tortured Soulを一つ手に入れてください。", "<急ごしらえの儀式の支度が、無造作に祭壇の上に集められている。書き付けの切れ端によれば、すべて揃っているようだ。足りないのは血の捧げ物と、Tortured Soulだけだ。\n\n周りのアンデッドは十分に苦しんでいるように見える。探しているものを持っているかもしれない。>", "<供物の石は不気味なほど静まり返っている。>", "<責め苦を受けた魂は、捧げ物の石の前で穢れた力を放つ。\n\nどうやら儀式の完成に近づいているようだ。>", 0xb60b70e3, 0x0d080853, 0x972297ea, 0x03dfcb1a, 0x2d800f13, "....." },
  [95884] = { "捧げ物の石", "Silverpine ForestのBeren's PerilでOffering Stoneを見つけてください。", "<書き付けの切れ端はほとんど判読できない。だが、まだ読める部分には、捧げ物の支度についての覚え書きがある。\n\n捧げ物の石と、儀式のことが書かれている。\n\nこの捧げ物の石は、近くで見つかるかもしれない。>", nil, "<石のざらついた表面には、奇妙な道具や品々が散らばっている。\n\nこれこそメモに書かれていた捧げ物の石に違いない。>", 0xa6de587b, 0x975b0b28, 0x838aeea9, nil, 0xaa91f891, "...m." },
  [95885] = { "血の捧げ物", "Tortured Soulを使い、Beren's PerilのOffering Stoneで血の捧げ物をしてください。", "<残るは血の捧げ物だけだ。\n\n書き付けの切れ端には「自ら望む生贄」とあった。\n\n強い恐怖が押し寄せてくる。>", "<供物の石は不気味なほど静まり返っている。>", "<捧げ物の石は今や沈黙している。どうやら儀式がその力を吸い尽くしたようだ。何のためだったのかは分からないが、もう終わったのだ。\n\nざらついた石はひび割れて崩れ落ち、もはや何の役目も持たない。\n\n残骸の中で何かがきらめいている……>", 0x3785a093, 0x7d15beec, 0xb34b8754, 0x03dfcb1a, 0x73aa5f70, "....." },
  [95981] = { "道の見張り", "SepulcherにいるShadow Priest Allisterのために、Dalaran Wizardを$N1人とDalaran Watcherを$N2人倒してください。", "奴らのペンダントを奪うのは最初の一歩にすぎない。もしKirin Torが本当にDalaranから遺物を絶えず送り込んでいるのなら、元から断たねばならん。\n\nAmbermillの周りの道で、Dalaranの魔術師と監視者を探せ。奴らのせいで、あまりにも長いあいだ我らの国境を自由に行き来されてきた。奴らの数を減らせれば、そもそもこのペンダントがSilverpine Forestに入ってくるのを止められるはずだ。", nil, "Dalaranを囲む障壁が消えてからというもの、Kirin Torは街道をがっちりと押さえている。何かを恐れているのは確かだ。\n\nだが今のところ、理由はどうでもいい。", 0xda0a241c, 0x94f2addc, 0x6d26148a, nil, 0xf9405a42, "...m." },
  [95998] = { "大自然", "Sam's Basic Campfireの近くに座り、Boosted Restのバフを受けるまで待って下さい。", "やあどうも、{class}。あんた、冒険者らしい顔つきをしてるね。いいことだ。世の中には、富と栄光を求める俺たちみたいな落ち着きのない連中がもっと必要なんだよ。\n\n外の世界は広くてね、うまくやっていくには荒野で生き抜く術を身につけなきゃならない。あんたのアウトドアの腕前がどれほどかは知らないが、覚える気があるなら、ひとつふたつ教えてやれると思うよ。\n\n火のそばに座って、楽にしてくれ。順を追って説明するよ。", nil, "さて、基本は身につけたから、次は専門技能を学びに行ってはどうだ？ 新しい専門技能にふさわしい、きちんとしたキャンプ用の設備の作り方も教えてくれるだろう。", 0x561c5fa2, 0xd61f22e7, 0xd463b94a, nil, 0x1938d14a, "...m." },
  [95999] = { "お尋ね者：Incinerator Gar'im", "Broken Staff of Incinerator Gar'imをLakeshireのMagistrate Solomonに届けてください。", "指名手配！Incinerator Gar'im。Render's Valleyにおけるオークの侵攻の首謀者。Stonewatch KeepのBlackrockと手を組んでいると見られる。\n\nIncinerator Gar'imに注意せよ。奴とその配下のShadowcastersは極めて危険である。Incinerator Gar'imを討ち取った証をMagistrate Solomonのもとへ届けた勇敢なる者には、相応の報酬が与えられる。", "そこに何を持っている、{race}？", "見事だ、{name}！ Incinerator Gar'imはStonewatch Keepの防備を固めようとしていた。この勝利で、砦を奪還できるかもしれない！", 0xfbb45123, 0x39291674, 0x96bd3b4a, 0x46dc827d, 0xaf05c26e, "....." },
})
